import os, sys

print("cwd:", os.getcwd())
for name in sorted(os.listdir(".")):
    full = os.path.join(".", name)
    if os.path.isfile(full):
        print("FILE", name, os.path.getsize(full))
    else:
        print("DIR ", name)

print("--- libraries ---")
for lib in ("pypdf", "reportlab", "pdfplumber", "PIL"):
    try:
        mod = __import__(lib)
        print(lib, "OK", getattr(mod, "__version__", "?"))
    except Exception as e:
        print(lib, "MISSING", repr(e))
